func privacyJSONSnapshot(t *testing.T, scope Scope) *Snapshot {
    t.Helper()
    config := DefaultConfig()
    config.Enabled = true
    config.Scopes = scope
    snapshot, err := Compile(config, []Rule{{Source: privacyJSONSource, Alias: "PHONE_1", Enabled: true}}, 1)
    if err != nil {
        t.Fatal(err)
    }
    return snapshot
}

func privacyJSONAt(t *testing.T, raw []byte, path string) json.RawMessage {
    t.Helper()
    value := json.RawMessage(raw)
    for _, key := range strings.Split(path, ".") {
        if key == "@" {
            text, err := DecodeJSONString(value)
            if err != nil {
                t.Fatalf("%s: inner document: %v", path, err)
            }
            value = json.RawMessage(text)
        } else if rawKind(value) == '[' {
            var array []json.RawMessage
            if err := json.Unmarshal(value, &array); err != nil {
                t.Fatal(err)
            }
            index, err := strconv.Atoi(key)
            if err != nil || index < 0 || index >= len(array) {
                t.Fatalf("bad array path %s", path)
            }
            value = array[index]
        } else {
            obj, err := decodeObject(value)
            if err != nil {
                t.Fatalf("%s: %v", path, err)
            }
            var exists bool
            value, exists = obj[key]
            if !exists {
                t.Fatalf("missing path %s", path)
            }
        }
    }
    return value
}

func privacyJSONEqual(t *testing.T, got, want []byte) {
    t.Helper()
    decode := func(raw []byte) any {
        decoder := json.NewDecoder(bytes.NewReader(raw))
        decoder.UseNumber()
        var value any
        if err := decoder.Decode(&value); err != nil {
            t.Fatal(err)
        }
        return value
    }
    if !reflect.DeepEqual(decode(got), decode(want)) {
        t.Fatalf("JSON mismatch: got %s; want %s", got, want)
    }
}

func TestPrivacyJSON(t *testing.T) {
    for _, fixture := range privacyJSONFixtures() {
        t.Run(fixture.name, func(t *testing.T) {
            for _, scope := range []Scope{0, Messages, ToolDefinitions, ToolCalls, ToolResponses, AllScopes, AllScopes &^ Messages, AllScopes &^ ToolDefinitions, AllScopes &^ ToolCalls, AllScopes &^ ToolResponses} {
                t.Run(strconv.Itoa(int(scope)), func(t *testing.T) {
                    snapshot := privacyJSONSnapshot(t, scope)
                    out, changed, err := snapshot.RewriteRequest(fixture.format, []byte(fixture.body))
                    if err != nil {
                        t.Fatal(err)
                    }
                    if changed != (scope != 0) {
                        t.Fatalf("changed=%v for scope %v", changed, scope)
                    }
                    if scope == 0 && string(out) != fixture.body {
                        t.Fatal("no-change did not preserve original body")
                    }
                    for path, selected := range fixture.selected {
                        text, err := DecodeJSONString(privacyJSONAt(t, out, path))
                        if err != nil {
                            t.Fatal(err)
                        }
                        want := privacyJSONSource
                        if scope&selected != 0 {
                            want = privacyJSONMarker
                        }
                        if text != want {
                            t.Fatalf("%s = %q; want %q", path, text, want)
                        }
                    }
                    for _, path := range fixture.untouched {
                        got, want := privacyJSONAt(t, out, path), privacyJSONAt(t, []byte(fixture.body), path)
                        if !bytes.Equal(got, want) {
                            t.Fatalf("untouched subtree %s changed: %s -> %s", path, want, got)
                        }
                    }
                    // A second request with no source in selected values is a
                    // byte-preserving no-op (generated markers are not sources).
                    again, changedAgain, err := snapshot.RewriteRequest(fixture.format, out)
                    if err != nil || changedAgain || !bytes.Equal(again, out) {
                        t.Fatal("no-change re-encoded body", err)
                    }
                    if fixture.name == "responses" {
                        input, _ := DecodeJSONString(privacyJSONAt(t, out, "input.5.input"))
                        want := privacyJSONSource + " {not JSON}"
                        if scope&ToolCalls != 0 {
                            want = privacyJSONMarker + " {not JSON}"
                        }
                        if input != want {
                            t.Fatal("custom tool input was inner-JSON parsed or missed")
                        }
                    }
                })
            }
        })
    }
    t.Run("response selectors", testPrivacyJSONSnapshots)
    t.Run("bidirectional matrix", testPrivacyJSONRestoreMatrix)
    t.Run("unselected content", testPrivacyJSONUnselected)
    t.Run("schema whitelist", testPrivacyJSONSchema)
    t.Run("fixed failures and rollback", testPrivacyJSONFailures)
    t.Run("unicode and nonrecursive", testPrivacyJSONUnicode)
}

func testPrivacyJSONRestoreMatrix(t *testing.T) {
    for _, fixture := range privacyJSONFixtures() {
        // Literal fixture markers replace literal fixture source everywhere,
        // including excluded fields/keys. Expectations still come from the
        // independent path matrix, not from a RewriteRequest result.
        raw := []byte(strings.ReplaceAll(fixture.body, privacyJSONSource, privacyJSONMarker))
        for _, scope := range []Scope{Messages, ToolDefinitions, ToolCalls, ToolResponses, AllScopes, AllScopes &^ Messages, AllScopes &^ ToolDefinitions, AllScopes &^ ToolCalls, AllScopes &^ ToolResponses} {
            transform := jsonTransform{snapshot: privacyJSONSnapshot(t, scope), restoring: true}
            var rewrite jsonRewrite
            switch fixture.name {
            case "chat":
                rewrite = transform.chatRequest
            case "responses":
                rewrite = transform.responsesRoot
            case "anthropic":
                rewrite = transform.anthropicRoot
            case "gemini":
                rewrite = transform.geminiRequest
            }
            out, changed, err := runJSON(transform.snapshot, raw, rewrite)
            if err != nil || !changed {
                t.Fatalf("%s scope %v restore: %v", fixture.name, scope, err)
            }
            for path, selected := range fixture.selected {
                path = strings.ReplaceAll(path, privacyJSONSource, privacyJSONMarker)
                got, err := DecodeJSONString(privacyJSONAt(t, out, path))
                want := privacyJSONMarker
                if scope&selected != 0 {
                    want = privacyJSONSource
                }
                if err != nil || got != want {
                    t.Fatalf("%s scope %v %s: %q want %q: %v", fixture.name, scope, path, got, want, err)
                }
            }
            for _, path := range fixture.untouched {
                path = strings.ReplaceAll(path, privacyJSONSource, privacyJSONMarker)
                if !bytes.Equal(privacyJSONAt(t, out, path), privacyJSONAt(t, raw, path)) {
                    t.Fatalf("%s restore changed excluded %s", fixture.name, path)
                }
            }
        }
    }
}

func testPrivacyJSONUnselected(t *testing.T) {
    cases := []struct {
        format llm.APIFormat
        scope  Scope
        raw    string
    }{
        {llm.APIFormatOpenAIChatCompletion, Messages, `{"messages":[{"tool_calls":[{"type":"custom"}],"function_call":{}}],"functions":[],"tools":[{"type":"custom"}]}`},
        {llm.APIFormatOpenAIChatCompletion, Messages, `{"messages":[{"tool_calls":[{"function":{"arguments":"{bad"}}]}]}`},
        {llm.APIFormatOpenAIChatCompletion, ToolDefinitions, `{"messages":42}`},
        {llm.APIFormatOpenAIResponse, ToolDefinitions, `{"input":42,"output":null}`},
        {llm.APIFormatOpenAIResponse, Messages, `{"input":[{"type":"computer_call","action":{"text":"13969909666"}},{"type":"function_call_output","output":{}},{"type":"function_call","arguments":"{bad"}]}`},
        {llm.APIFormatAnthropicMessage, ToolDefinitions, `{"messages":42,"content":null}`},
        {llm.APIFormatAnthropicMessage, Messages, `{"content":[{"type":"unknown_tool_result","content":{}},{"type":"web_search_tool_result","content":{"type":"new_envelope"}}]}`},
        {llm.APIFormatGeminiContents, Messages, `{"contents":[{"parts":[{"function_call":{"args":{}}}]}]}`},
        {llm.APIFormatGeminiContents, ToolDefinitions, `{"contents":null,"systemInstruction":42}`},
    }
    for i, tc := range cases {
        out, changed, err := privacyJSONSnapshot(t, tc.scope).RewriteRequest(tc.format, []byte(tc.raw))
        if err != nil || changed || string(out) != tc.raw {
            t.Fatalf("unselected case %d: changed=%v err=%v", i, changed, err)
        }
    }
    // A type field at the root of an explicitly business tool result is a
    // business string value, not an Anthropic envelope tag.
    raw := []byte(`{"content":[{"type":"tool_result","content":{"type":"13969909666","id":"13969909666","name":"13969909666","description":"13969909666"}}]}`)
    out, changed, err := privacyJSONSnapshot(t, ToolResponses).RewriteRequest(llm.APIFormatAnthropicMessage, raw)
    if err != nil || !changed {
        t.Fatal("business result object rejected", err)
    }
    for _, key := range []string{"type", "id", "name", "description"} {
        text, _ := DecodeJSONString(privacyJSONAt(t, out, "content.0.content."+key))
        if text != privacyJSONMarker {
            t.Fatal("business key treated as protocol field", key)
        }
    }
    // A later selected capability failure must discard an earlier successful edit.
    raw = []byte(`{"input":[{"type":"message","content":"13969909666"},{"type":"function_call_output","output":{}}]}`)
    out, changed, err = privacyJSONSnapshot(t, AllScopes).RewriteRequest(llm.APIFormatOpenAIResponse, raw)
    if err != ErrUnsupportedContent || changed || !bytes.Equal(out, raw) {
        t.Fatal("partial object escaped rollback")
    }
}

